create schema if not exists private;
revoke all on schema private from public,anon;
grant usage on schema private to authenticated;
alter function public.is_household_member(uuid) set schema private;
alter function public.create_household(text) set schema private;
alter function public.invite_partner(text) set schema private;
alter function public.accept_household_invite(text) set schema private;
revoke all on function private.is_household_member(uuid),private.create_household(text),private.invite_partner(text),private.accept_household_invite(text) from public,anon;
grant execute on function private.is_household_member(uuid),private.create_household(text),private.invite_partner(text),private.accept_household_invite(text) to authenticated;
create function public.create_household(person_name text) returns uuid language sql security invoker set search_path='' as $$select private.create_household(person_name);$$;
create function public.invite_partner(partner_email text) returns text language sql security invoker set search_path='' as $$select private.invite_partner(partner_email);$$;
create function public.accept_household_invite(invite_token text) returns uuid language sql security invoker set search_path='' as $$select private.accept_household_invite(invite_token);$$;
revoke all on function public.create_household(text),public.invite_partner(text),public.accept_household_invite(text) from public,anon;
grant execute on function public.create_household(text),public.invite_partner(text),public.accept_household_invite(text) to authenticated;
create policy invites_no_direct_access on public.household_invites for all to authenticated using(false) with check(false);
create index finance_created_by_idx on public.finance_records(created_by);
create index household_invites_household_idx on public.household_invites(household_id);
create index households_owner_idx on public.households(owner_id);
alter policy records_insert on public.finance_records with check(private.is_household_member(household_id) and created_by=(select auth.uid()));
